export const NEW_ITEMS=ITEMS.slice(3);
export function stockFor(chapter){return ITEMS.filter(i=>i.chapter<=chapter);}
export function buyItem(state,id,count=1){const i=ITEMS.find(i=>i.id===id);if(!i||!Number.isInteger(count)||count<1||count>99||i.chapter>state.chapter||state.gold<i.price*count)return false;state.gold-=i.price*count;state.items[id]=(state.items[id]||0)+count;return true;}
export function chapterTreasure(chapter){return NEW_ITEMS[(chapter-1)%NEW_ITEMS.length];}
