export const BESTIARY=[...SPECIES,...SPECIES.map((s,i)=>({...s,id:s.id+'-elder',name:'Elder '+s.name,chapter:Math.min(24,14+Math.floor(roadOrder.indexOf(i)/2)),elder:true}))];

function applyEnemySpecies(enemy,chapter,s){return {...enemy,species:s.id,name:s.name,atlas:s.atlas,sprite:s.sprite,role:s.role,trait:s.trait,element:s.element,drop:s.drop,power:enemy.power*(s.elder?1.1:1),move:(s.elder?'Elder ':'')+s.move,moveShape:s.elder?(s.shape==='line'?'burst':'line'):s.shape,moveStatus:s.status,habitat:s.habitat,elder:!!s.elder,armor:s.role==='guard'?55+chapter*4:0,maxArmor:s.role==='guard'?55+chapter*4:0,color:s.elder?'#e6c88c':enemy.color};}
/** Explicit local formations reuse the delivered species mechanics and current
 * encounter tier. Unknown or not-yet-introduced identities are refused. */
export function decorateEnemySpecies(enemy,chapter,speciesId){const s=BESTIARY.find(s=>s.id===speciesId);if(!s||enemy.boss||chapter<2||s.chapter>chapter)return null;return applyEnemySpecies(enemy,chapter,s);}
export function decorateEnemy(enemy,chapter,index=0){if(chapter<2||enemy.boss)return enemy;const elder=chapter>=14,slot=((chapter-(elder?14:2))*2+index)%24,base=roadOrder[(slot+24)%24],s=BESTIARY[base+(elder?24:0)];return applyEnemySpecies(enemy,chapter,s);}
export function creatureDrops(chapter){return [...new Set(Array.from({length:2},(_,i)=>decorateEnemy({power:1},chapter,i).drop).filter(Boolean))];}
function applySupplyBase(battle,inventory,id,actor,target){const i=ITEMS.find(i=>i.id===id);if(!i||!(inventory[id]>0)||!actor||actor.hp<=0||actor.atb<1||battle.ended)return false;
 const alive=battle.heroes.filter(h=>h.hp>0),asset=battle.objective?.asset,healable=[...alive,...(asset?.hp>0?[asset]:[])],wounded=healable.filter(h=>h.hp<h.maxHp).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0],lowMP=alive.filter(h=>h.mp<h.maxMp).sort((a,b)=>a.mp/a.maxMp-b.mp/b.maxMp)[0],dead=battle.heroes.filter(h=>h.hp<=0),bad=['burn','slow','wet','shock','exposed','brittle','stagger'];let ok=false;
 const heal=(h,v)=>{h.hp=Math.min(h.maxHp,h.hp+Math.round(h.maxHp*v));};
 if(i.effect==='heal'&&wounded){wounded.hp=Math.min(wounded.maxHp,wounded.hp+Math.max(id==='tonic'?100:1,Math.round(wounded.maxHp*i.value)));ok=true;}
 else if(i.effect==='mp'&&lowMP){lowMP.mp=Math.min(lowMP.maxMp,lowMP.mp+Math.max(id==='ether'?20:1,Math.round(lowMP.maxMp*i.value)));ok=true;}
 else if(i.effect==='revive'&&dead.length){dead[0].hp=Math.max(1,Math.round(dead[0].maxHp*i.value));ok=true;}
 else if(i.effect==='reviveAll'&&dead.length){dead.forEach(h=>h.hp=Math.max(1,Math.round(h.maxHp*i.value)));ok=true;}
 else if(i.effect==='healAll'&&wounded){healable.forEach(h=>heal(h,i.value));ok=true;}
 else if(i.effect==='mpAll'&&lowMP){alive.forEach(h=>h.mp=Math.min(h.maxMp,h.mp+Math.round(h.maxMp*i.value)));ok=true;}
 else if(i.effect==='cleanse'){const h=alive.find(h=>bad.some(k=>h.status[k]));if(h){bad.forEach(k=>delete h.status[k]);ok=true;}}
 else if(['cool','insulate','shield','guard','haste'].includes(i.effect)){const h=actor;if(i.effect==='cool')delete h.status.burn;if(i.effect==='insulate')delete h.status.shock;if(['cool','insulate','shield'].includes(i.effect))h.status.shield=Math.min(300,(h.status.shield||0)+i.value);else h.status[i.effect]=i.value;ok=true;}
 else if(i.effect==='strain'){const h=[...alive].sort((a,b)=>(b.strain||0)-(a.strain||0))[0];if(h?.strain>0){h.strain=Math.max(0,h.strain-i.value);ok=true;}}
 else if(i.effect==='slowAll'&&battle.livingEnemies.length){battle.livingEnemies.forEach(e=>e.status.slow=i.value);ok=true;}
 else if(i.effect==='blastAll'&&battle.livingEnemies.length){for(const e of battle.livingEnemies)battle.damage(actor,e,i.value,{color:'#b7eadc'});ok=true;}
 else if(target&&battle.enemies.includes(target)&&target.hp>0&&!target.withdrawn&&['burn','slow','wet','exposed','shock','shatter','leech'].includes(i.effect)){if(i.effect==='shatter'){target.armor=Math.max(0,target.armor-i.value);interruptCharge(battle,target,actor,{core:'earth',stagger:2});}else{const hit=battle.damage(actor,target,i.value,{color:'#e3c48b'});if(i.effect==='leech')actor.hp=Math.min(actor.maxHp,actor.hp+(hit?.damage||0));else if(target.hp>0)target.status[i.effect]=i.effect==='shock'?2:7;}ok=true;}
 if(!ok){
  if(i.effect==='rally'){const others=alive.filter(h=>h!==actor&&h.atb<1);for(const h of others)h.atb=Math.min(1,h.atb+i.value);ok=others.length>0;}
  else if(i.effect==='cleanseAll'){const afflicted=alive.filter(h=>bad.some(k=>h.status[k]));for(const h of afflicted)bad.forEach(k=>delete h.status[k]);ok=afflicted.length>0;}
  else if(i.effect==='shieldAll'){for(const h of healable)h.status.shield=Math.min(300,(h.status.shield||0)+i.value);ok=alive.length>0;}
  else if(i.effect==='strainAll'){ok=alive.some(h=>h.strain>0);for(const h of alive)h.strain=Math.max(0,(h.strain||0)-i.value);}
  else if(i.effect==='dispelAll'){for(const e of battle.livingEnemies){if(['guard','haste','shield','glazed'].some(k=>e.status[k]))ok=true;for(const k of ['guard','haste','shield','glazed'])delete e.status[k];}}
  else if(i.effect==='interruptAll'){for(const e of battle.livingEnemies){if(e.intent||e.armor>0){ok=true;e.armor=Math.max(0,e.armor-i.value);interruptCharge(battle,e,actor,{core:'earth',stagger:2});}}}
  else if(i.effect==='markAll'){for(const e of battle.livingEnemies)e.status.exposed=i.value;ok=battle.livingEnemies.length>0;}
  else if(i.effect==='tideAll'){for(const e of [...battle.livingEnemies]){battle.damage(actor,e,i.value,{color:'#72cde0'});if(e.hp>0)e.status.wet=7;}ok=true;}
  else if(i.effect==='delayAll'){for(const e of battle.livingEnemies){if(e.atb>0||e.intent)ok=true;e.atb=Math.max(0,e.atb-i.value);if(e.intent){e.intent.left+=1;e.intent.total+=1;}}}
  else if(i.effect==='reviveShield'&&dead.length){dead[0].hp=Math.max(1,Math.round(dead[0].maxHp*i.value));dead[0].status.shield=90;ok=true;}
  else if(i.effect==='mpSiphon'&&target?.hp>0&&battle.enemies.includes(target)){battle.damage(actor,target,i.value,{color:'#a3c4e3'});actor.mp=Math.min(actor.maxMp,actor.mp+12);ok=true;}
  else if(i.effect==='healCleanse'){const h=healable.find(h=>bad.some(k=>h.status[k]))||wounded;if(h){heal(h,i.value);bad.forEach(k=>delete h.status[k]);ok=true;}}
  else if(['hasteAll','guardAll'].includes(i.effect)){for(const h of alive)h.status[i.effect==='hasteAll'?'haste':'guard']=i.value;ok=alive.length>0;}
 }
 if(!ok)return false;inventory[id]--;actor.atb=0;return true;
}

/** One paid action, one source tag: thrown items participate in the same reactions as spells. */
export function applySupply(battle,inventory,id,actor,target){const item=ITEMS.find(i=>i.id===id);if(!item)return false;const all=[...battle.heroes,...battle.enemies,...(battle.objective?.asset?[battle.objective.asset]:[])],before=new Map(all.map(h=>[h.id,JSON.stringify([h.hp,h.mp,h.strain,h.status,h.armor,h.intent,h!==actor?h.atb:null])])),prior=battle.pendingSupply,stats=new Map(battle.heroes.map(h=>[h.id,{hp:h.hp,mp:h.mp,strain:h.strain,shield:h.status.shield||0}]));const roleBefore=new Map(all.map(h=>[h.id,{...h.status}]));const context={item,steamTargets:new Set()};battle.pendingSupply=context;let ok=false;try{ok=applySupplyBase(battle,inventory,id,actor,target);if(!ok)return false;for(const h of all){if(context.steamTargets.has(h.id))delete h.status.burn;if(battle.context?.tags?.includes('arid')&&h.status.wet)h.status.wet=Math.min(3,h.status.wet);}const targets=all.filter(h=>before.get(h.id)!==JSON.stringify([h.hp,h.mp,h.strain,h.status,h.armor,h.intent,h!==actor?h.atb:null]));if(battle.context?.tags?.includes('heat')&&(item.effect==='shieldAll'||item.id==='wardPearl'))for(const h of targets.filter(h=>battle.heroes.includes(h)&&h.status.shield)){h.status.glazed=6;reactionEvent(battle,'vitrify',actor,h,{core:'ward',terrain:true});}if((actor.battleRelics||[]).slice(0,2).includes('graftroot')&&['heal','healAll','healCleanse'].includes(item.effect))for(const h of targets.filter(h=>battle.heroes.includes(h))){const old=stats.get(h.id),intended=Math.max(item.id==='tonic'?100:0,h.maxHp*item.value),surplus=Math.max(0,old.hp+intended-h.maxHp);if(surplus){h.status.shield=Math.min(300,(h.status.shield||0)+Math.min(80,Math.round(surplus*.5)));reactionEvent(battle,'renewal',actor,h,{core:'mend',item:item.id});}}for(const h of battle.heroes){const old=stats.get(h.id);for(const [resource,delta]of [['HP',h.hp-old.hp],['MP',h.mp-old.mp],['strain',old.strain-h.strain],['shield',(h.status.shield||0)-old.shield]])if(delta>0)battle.event({type:'resource',actor:h,resource,amount:Math.round(delta)});}approachSupply(battle,actor,item,targets,roleBefore);battle.event({type:'supply',actor,item,targets:targets.length?targets:[actor],visual:supplyVisual(item),core:supplyCore(item)});return true;}finally{battle.pendingSupply=prior;}}
