export const FRONTIER_SPECIES=frontierNames.map((name,i)=>({id:'frontier-'+i,name,element:['earth','shade','earth','volt','flame','gale','tide','ward','tide','earth','shade','volt','frost','frost','earth','gale','mend','earth','shade','volt','volt','gale','earth','gravity'][i],role:['guard','predator','guard','scout','predator','scout','mender'][i%7],sprite:i,atlas:'bestiary3',shape:i%2?'line':'burst',status:['slow','exposed','burn','shock','wet'][i%5],move:frontierMoves[i],trait:['forge','tempo','pressure','chorus','siphon','molt','erase'][i%7],habitat:['Amber Dunes','Saltglass Flats','Cactus Barrens','Ember Caldera','Coral Shoals','Mangrove Delta','Crystal Caverns','Glacier Reach','Aurora Tundra','Sporewood','Storm Peaks','Marble Wastes'][Math.floor(i/2)],chapter:Math.min(24,2+Math.floor(i/2)),drop:NEW_ITEMS[(i*5)%NEW_ITEMS.length].id,tell:frontierMoves[i]+': '+(i%2?'step sideways from the marked line.':'leave the marked circle.'),lore:'A resident of the frontier. Its movements follow the local terrain rather than the city machinery.'}));
