export function frontierEnemy(enemy,id){const s=FRONTIER_BESTIARY.find(s=>s.id===id);if(!s)return enemy;return {...enemy,species:s.id,name:s.name,atlas:s.atlas,sprite:s.sprite,role:s.role,trait:s.trait,element:s.element,drop:s.drop,move:s.move,moveShape:s.shape,moveStatus:s.status,habitat:s.habitat,hue:s.hue||0,armor:s.role==='guard'?(enemy.chapter||s.chapter)*4+45:0,maxArmor:s.role==='guard'?(enemy.chapter||s.chapter)*4+45:0};}
